import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const Navbar = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
    toast.success('Logged out successfully');
    navigate('/login');
  };

  return (
    <nav style={styles.navbar}>
      <div style={styles.navLeft}>
        <span style={styles.logo} onClick={() => navigate('/')}>⚡ CodeArena</span>
        <span style={styles.separator}>|</span>
        <button onClick={() => navigate('/problems')} style={styles.navLink}>Problems</button>
        <span style={styles.separator}>|</span>
        <button onClick={() => navigate('/submissions')} style={styles.navLink}>Submissions</button>
        <span style={styles.separator}>|</span>
        {(user?.role === 'admin' || user?.role === 'setter') && (
          <>
            <button onClick={() => navigate('/create-problem')} style={styles.navLink}>Create</button>
            <span style={styles.separator}>|</span>
          </>
        )}
        <span style={styles.userName}>{user?.username}</span>
        <span style={styles.separator}>|</span>
        <button onClick={handleLogout} style={styles.logoutBtn}>
          Logout
        </button>
      </div>
      <div style={styles.navRight}>
        <button style={styles.refreshBtn} onClick={() => window.location.reload()}>
          🔄 REFRESH
        </button>
        <span style={styles.weather}>☀️ 29°</span>
      </div>
    </nav>
  );
};

const styles = {
  navbar: {
    background: '#ffffff',
    padding: '10px 24px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    borderBottom: '1px solid #e8e8e8',
    flexWrap: 'wrap',
    gap: '8px',
  },
  navLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    flexWrap: 'wrap',
  },
  logo: {
    fontSize: '16px',
    fontWeight: 700,
    color: '#1a1a2e',
    cursor: 'pointer',
  },
  separator: {
    color: '#d0d0d0',
    fontSize: '13px',
  },
  navLink: {
    background: 'transparent',
    border: 'none',
    color: '#555',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 500,
    padding: '4px 0',
  },
  userName: {
    fontSize: '13px',
    color: '#1a1a2e',
    fontWeight: 600,
  },
  logoutBtn: {
    background: 'transparent',
    border: 'none',
    color: '#ef5350',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 500,
    padding: '4px 0',
  },
  navRight: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  },
  refreshBtn: {
    padding: '4px 14px',
    background: '#6C63FF',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    fontSize: '11px',
    fontWeight: 600,
    cursor: 'pointer',
  },
  weather: {
    fontSize: '14px',
    fontWeight: 500,
    color: '#333',
  },
};

export default Navbar;
